var e=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,5),t={text(t){return{id:e(),type:`text`,content:t}},image(t,n=``,r=70){return{id:e(),type:`image`,content:t||``,alt:n,imageWidth:r}},video(t,n=``){return{id:e(),type:`video`,content:t||``,alt:n}},divider(){return{id:e(),type:`divider`}},callout(t,n=`info`){return{id:e(),type:`callout`,content:t,calloutStyle:n}},code(t,n=`javascript`){return{id:e(),type:`code`,content:t,language:n}},steps(t,n){return{id:e(),type:`steps`,sectionTitle:t,items:n}},accordion(t,n){return{id:e(),type:`accordion`,sectionTitle:t,items:n}},tabs(t,n){return{id:e(),type:`tabs`,sectionTitle:t,items:n}},timeline(t,n){return{id:e(),type:`timeline`,sectionTitle:t,items:n}},quiz(t){return{id:e(),type:`quiz`,content:``,questions:t}}};function n(t,n,r,i={}){return{id:e(),name:t,template:n||`title-text`,blocks:r,desc:i.desc||``,duration:i.duration||10,preview:i.preview||!1,required:i.required===void 0?!0:i.required}}function r(t,n,r=!0){return{id:e(),name:t,open:r,lessons:n}}var i=(e,t=``)=>({type:`image`,content:`https://images.unsplash.com/${e}?w=800&h=500&fit=crop&auto=format`,alt:t,imageWidth:70}),a={procedure:`photo-1581091226825-a6a2a5aee158`,safety:`photo-1581092160562-40aa08e78837`,checklist:`photo-1450101499163-c8848c66ca85`,tools:`photo-1530124566582-a618bc2615dc`,onboarding:`photo-1522071820081-009f0129c71c`,culture:`photo-1529156069898-49953b60c83e`,office:`photo-1497366216548-37526070297c`,remote:`photo-1588196749597-9ff075ee6b5b`,laptop:`photo-1498050108023-c5249f4df085`,sales:`photo-1552664730-d307ca884978`,meeting:`photo-1600880292203-757bb62b4baf`,cybersecurity:`photo-1550751827-4bd374c3f58b`,security:`photo-1563013544-824ae1b704d3`,password:`photo-1614064641938-3bbee52942c7`,company:`photo-1486406143026-af6277b38e60`,team:`photo-1517245386807-bb43f82c33c4`,presentation:`photo-1559228451-c9e3f68b2db2`,learning:`photo-1503676260728-1c00da094a0b`,health:`photo-1571019613454-1cb2f99b2d8b`,productivity:`photo-1484480974693-6ca0a78fb36b`,communication:`photo-1577563908411-5077b6dc7624`},o=e=>`https://www.youtube.com/watch?v=${e}`,s=[{id:`demonstrate-procedure`,name:`Demonstrate a Procedure`,description:`Step-by-step walkthrough for teaching any repeatable process, from lab protocols to field operations.`,emoji:`📋`,colorIdx:0,tags:`template, procedure, steps, how-to`,getCourse:()=>({name:`Procedure Mastery`,subtitle:`Master any repeatable process with clear step-by-step instruction`,description:`<p>This course provides a structured framework for teaching step-by-step procedures. Learners follow along with clear demonstrations, practice each stage hands-on, and verify understanding with checkpoint assessments. Perfect for lab protocols, field operations, manufacturing processes, and service workflows.</p>`,emoji:`📋`,colorIdx:0,status:`draft`,tags:`template, procedure, steps, how-to`,access:`free`,modules:[r(`Preparation & Overview`,[n(`Introduction to the Procedure`,`slide-layout`,[t.text(`<h2>Welcome to Procedure Mastery</h2><p>In this course, you will learn how to execute a repeatable procedure with <b>precision</b> and <b>confidence</b>. Whether you are working in a lab, on a factory floor, or in the field, mastering procedures is the foundation of quality work.</p><p>By the end of this module, you will be able to:</p><ul><li>Understand what the procedure accomplishes and why each step matters</li><li>Identify all tools and materials required before starting</li><li>Complete a pre-procedure checklist to ensure readiness</li></ul>`),{id:e(),...i(a.procedure,`A professional preparing equipment for a procedure`)},t.callout(`<p><strong>Key Insight:</strong> Studies show that 73% of procedural errors happen because a step was skipped or performed out of sequence. A structured approach eliminates guesswork.</p>`,`tip`)],{desc:`Overview of what learners will accomplish and why this procedure matters.`,duration:12}),n(`Required Tools & Safety Precautions`,`two-col`,[t.text(`<h2>Tools & Equipment Checklist</h2><p>Before beginning any procedure, gather the following:</p><ul><li><b>Primary tools</b> — The essential instruments or devices needed for the procedure</li><li><b>Safety equipment</b> — PPE including gloves, goggles, lab coat, or hard hat as required</li><li><b>Measurement devices</b> — Calipers, thermometers, timers, or gauges</li><li><b>Documentation</b> — Log sheets, checklists, or digital tracking tools</li></ul>`),t.text(`<h3>Safety First</h3><p>Review these safety protocols before starting:</p><ul><li><b>Personal Protective Equipment (PPE):</b> Always wear the required gear — no exceptions.</li><li><b>Environmental checks:</b> Verify ventilation, temperature, and clearance zones.</li><li><b>Emergency procedures:</b> Know the location of eyewash stations, fire extinguishers, and first aid kits.</li><li><b>Lock-out/tag-out:</b> If applicable, confirm energy sources are isolated.</li></ul>`)],{desc:`List of tools, materials, and safety precautions needed before starting.`,duration:10}),n(`Pre-Procedure Checklist`,`steps`,[t.steps(`Before You Begin — Complete This Checklist`,[{title:`Step 1: Review the Procedure Document`,content:`<p>Read through the entire procedure from start to finish. Highlight any steps that are new or unfamiliar. <b>Do not skip this step</b> — familiarity prevents mid-procedure surprises.</p>`},{title:`Step 2: Gather All Required Materials`,content:`<p>Lay out every tool, material, and piece of equipment in the order you will need them. Use a visual layout board if available. This is called <em>mise en place</em> — everything in its place.</p>`},{title:`Step 3: Inspect Equipment`,content:`<p>Test each tool and device. Calibrate instruments if required. Replace any worn or damaged items immediately. A faulty tool can compromise the entire procedure.</p>`},{title:`Step 4: Verify Environmental Conditions`,content:`<p>Check temperature, humidity, lighting, and cleanliness. Some procedures require specific environmental parameters. Document baseline readings.</p>`},{title:`Step 5: Confirm Authorization`,content:`<p>Ensure you have the necessary permissions to proceed. Some procedures require supervisor sign-off or a second set of eyes.</p>`}]),t.callout(`<p><strong>Pro Tip:</strong> Print this checklist and laminate it. Use a dry-erase marker to track completion for each run. This simple habit reduces missed steps by over 60%.</p>`,`tip`)],{desc:`A downloadable checklist covering every prerequisite step.`,duration:8})]),r(`Step-by-Step Walkthrough`,[n(`Phase 1: Initial Setup`,`slide-layout`,[t.text(`<h2>Setting Up for Success</h2><p>The first phase of any procedure is the setup. This is where you position equipment, configure settings, and prepare the workspace. Rushing through setup is the <b>#1 cause of procedural failures</b>.</p><p>During setup, focus on:</p><ul><li>Positioning all tools within easy reach in the correct sequence</li><li>Configuring machine settings according to the procedure specifications</li><li>Double-checking connections, power sources, and safety interlocks</li></ul>`),{id:e(),...i(a.tools,`Tools and equipment arranged on a workbench`)},t.callout(`<p><strong>Remember:</strong> If you are interrupted during setup, start the setup checklist over from the beginning. Never assume you remember where you left off.</p>`,`warning`)],{desc:`Initial setup steps with visual guides.`,duration:15}),n(`Phase 2: Core Procedure Execution`,`steps`,[t.steps(`Executing the Procedure — Step by Step`,[{title:`Execute Step 1`,content:`<p>Begin the first operational step. Move deliberately, not quickly. Speed comes with practice — <b>accuracy comes from attention</b>. Document your start time.</p>`},{title:`Verify After Step 1`,content:`<p>Before moving on, confirm the outcome matches the expected result. If something looks off, <b>stop and troubleshoot</b>. Do not proceed until the current step is verified.</p>`},{title:`Execute Step 2`,content:`<p>Proceed to the next step in sequence. Maintain consistent technique — hand position, tool angle, and pressure should match the documented standard.</p>`},{title:`Verify After Step 2`,content:`<p>Check measurements, readings, or visual indicators. Log the result. If your organization uses digital tracking, enter data now to avoid forgetting later.</p>`},{title:`Continue Through Remaining Steps`,content:`<p>Repeat the execute-verify cycle for each step in the procedure. <b>Never skip verification</b> — it is the safety net that catches errors before they compound.</p>`},{title:`Final Verification`,content:`<p>Complete an end-to-end review. Check all measurements against baseline expectations. Sign off on the procedure log. Clean and store all tools.</p>`}]),{id:e(),...i(a.checklist,`A person checking off items on a procedure checklist`)}],{desc:`The main procedure broken into numbered steps.`,duration:18}),n(`Phase 3: Verification & Quality Check`,`quiz-focus`,[t.text(`<h2>Verifying Your Work</h2><p>Verification is not optional — it is part of the procedure. Every step must be confirmed before the procedure is considered complete.</p><h3>Verification Methods</h3><ul><li><b>Visual inspection:</b> Check for correct assembly, proper alignment, and absence of defects</li><li><b>Measurement confirmation:</b> Use calibrated instruments to verify critical dimensions or parameters</li><li><b>Functional test:</b> If applicable, run a quick functional check to confirm the outcome works as expected</li><li><b>Peer review:</b> For high-stakes procedures, have a colleague independently verify the result</li></ul>`),t.quiz([{q:`What is the most common cause of procedural errors?`,subtype:`multiple-choice`,options:[`Skipping steps or performing them out of sequence`,`Using the wrong tools`,`Poor lighting`,`Lack of training`],correct:0},{q:`During the execute-verify cycle, you should proceed to the next step even if the current step does not match expectations.`,subtype:`true-false`,correct:1},{q:`The verification method where a colleague independently checks your result is called a _______.`,subtype:`fill-blank`,correct:`peer review`},{q:`Match each verification type with its purpose:`,subtype:`matching`,pairs:[{left:`Visual inspection`,right:`Check for defects and alignment`},{left:`Measurement confirmation`,right:`Verify critical dimensions`},{left:`Functional test`,right:`Confirm the outcome works`}]}])],{desc:`Verify each step was completed correctly, with a knowledge check.`,duration:12})]),r(`Practice & Assessment`,[n(`Guided Practice Session`,`media-guide`,[t.video(o(`TjPFZaK1qJo`),`Standard Operating Procedure demonstration video`),t.text(`<h2>Follow Along: Guided Practice</h2><p>Watch the demonstration video above, then practice the procedure yourself. Use the checklist from Module 1 and follow the execute-verify cycle from Module 2.</p><p>Key points to focus on during practice:</p><ul><li>Maintain consistent pace — do not rush</li><li>Verbalize each step as you perform it (this reinforces memory)</li><li>If you make a mistake, stop, document what went wrong, and restart from the last verified step</li></ul>`),t.callout(`<p><strong>Practice Tip:</strong> Research shows that <em>deliberate practice</em> — where you focus on improving specific aspects with immediate feedback — is 4x more effective than simple repetition. After each practice run, identify one thing to improve next time.</p>`,`tip`)],{desc:`Follow along with an instructor-led demonstration.`,duration:20}),n(`Common Mistakes & Troubleshooting`,`callout`,[t.text(`<h2>Common Pitfalls to Avoid</h2><p>Even experienced practitioners make mistakes. Here are the most common procedural errors and how to prevent them:</p>`),t.callout(`<p><strong>Mistake #1: Skipping the Warm-Up.</strong> Jumping straight into the procedure without reviewing the steps leads to tunnel vision. <b>Fix:</b> Always do a 2-minute mental walkthrough before starting.</p>`,`warning`),t.callout(`<p><strong>Mistake #2: Ignoring Small Deviations.</strong> A slightly off reading might seem insignificant, but small errors compound. <b>Fix:</b> If a measurement is off by even 5%, stop and investigate.</p>`,`warning`),t.callout(`<p><strong>Mistake #3: Rushing Through Verification.</strong> Under time pressure, people tend to glance rather than verify. <b>Fix:</b> Use a physical checklist and initial each item — the tactile act reinforces thoroughness.</p>`,`warning`),t.callout(`<p><strong>Mistake #4: Not Documenting Anomalies.</strong> If something unusual happens and you do not record it, the next person will face the same surprise. <b>Fix:</b> Keep a logbook. Write down anything that deviates from normal.</p>`,`danger`)],{desc:`Pitfalls, troubleshooting, and pro tips.`,duration:10}),n(`Final Assessment`,`assessment`,[t.text(`<h2>Procedure Mastery Assessment</h2><p>Congratulations on completing the course! This final assessment tests your understanding of the entire procedure workflow — from preparation through execution to verification.</p>`),t.quiz([{q:`What should you do if you are interrupted during the setup phase?`,subtype:`multiple-choice`,options:[`Restart the setup checklist from the beginning`,`Pick up where you think you left off`,`Skip the remaining setup steps`,`Ask a colleague what to do`],correct:0},{q:`The execute-verify cycle means: perform a step, confirm the result, then move to the next step.`,subtype:`true-false`,correct:0},{q:`Before starting any procedure, you should always review the entire procedure document from _______ to _______.`,subtype:`fill-blank`,correct:`start to finish`},{q:`Which of the following is NOT a verification method covered in this course?`,subtype:`multiple-choice`,options:[`Visual inspection`,`Measurement confirmation`,`Guessing based on experience`,`Peer review`],correct:2},{q:`What is the term for laying out all tools and materials in order before starting a procedure?`,subtype:`multiple-choice`,options:[`Mise en place`,`Kaizen`,`Kanban`,`Poka-yoke`],correct:0}])],{desc:`Comprehensive quiz to verify mastery of the procedure.`,duration:12})])]})},{id:`onboard-person`,name:`Onboard a Person`,description:`A complete onboarding journey — company culture, tools, workflows, and role expectations.`,emoji:`🚀`,colorIdx:1,tags:`template, onboarding, hr, orientation`,getCourse:()=>({name:`Welcome Aboard`,subtitle:`Your complete onboarding journey — culture, tools, and role success`,description:`<p>A comprehensive onboarding course designed to get new team members up to speed quickly. Covers company culture, essential tools, team workflows, and role-specific expectations. By the end, you will feel confident, connected, and ready to make an impact.</p>`,emoji:`🚀`,colorIdx:1,status:`draft`,tags:`template, onboarding, hr, orientation`,access:`free`,modules:[r(`Welcome & Culture`,[n(`Welcome Message from Leadership`,`slide-layout`,[t.text(`<h2>Welcome to the Team!</h2><p>We are thrilled to have you on board. You were selected from a competitive pool of candidates because we believe you bring something special to our organization.</p><p>In this first lesson, you will hear directly from our leadership team about:</p><ul><li>Why our company exists and the problem we are passionate about solving</li><li>Where we are headed in the next 3-5 years</li><li>What we value most in our team members</li></ul>`),{id:e(),...i(a.team,`Diverse team collaborating in a modern office`)},t.callout(`<p><strong>From the CEO:</strong> "Our greatest asset is our people. We built this company on the belief that empowered teams do extraordinary work. Welcome — we are glad you are here."</p>`,`info`)],{desc:`A personal welcome from the leadership team and company vision.`,duration:10}),n(`Our Mission, Vision & Values`,`full-text`,[t.text(`<h2>What Drives Us</h2><p>Every great organization is built on a clear sense of purpose. Here is what drives us every day:</p><h3>Our Mission</h3><p>To <b>empower teams</b> through innovative solutions that make work simpler, faster, and more impactful. We exist to solve real problems for real people.</p><h3>Our Vision</h3><p>A world where every organization has access to the tools and knowledge they need to reach their full potential — regardless of size, budget, or location.</p><h3>Our Core Values</h3><ul><li><b>Curiosity First:</b> We ask questions, challenge assumptions, and never stop learning.</li><li><b>Ownership Mindset:</b> We take responsibility for outcomes, not just tasks.</li><li><b>Radical Collaboration:</b> The best ideas come from diverse perspectives working together.</li><li><b>Customer Obsession:</b> Every decision starts with the question: "How does this help our users?"</li><li><b>Integrity Always:</b> We do the right thing, even when no one is watching.</li></ul>`)],{desc:`Deep dive into what drives the organization.`,duration:12}),n(`Company History & Milestones`,`tabs`,[t.tabs(`Our Journey`,[{title:`The Beginning`,content:`<p>Our company was founded in 2018 by a small team of engineers and educators who saw a gap in how organizations train their people. Starting from a garage office with just three laptops and a big vision, the founding team spent the first year interviewing over 200 training managers to understand their pain points.</p>`},{title:`Growth Phase`,content:`<p>By 2020, we had grown to 50 team members across 4 countries. We launched our flagship platform, onboarded our first 100 enterprise customers, and raised Series A funding. Despite the global pandemic, our remote-first culture allowed us to thrive while helping clients transition to digital training.</p>`},{title:`Today`,content:`<p>Today, we serve over 500 organizations worldwide with a team of 200+ passionate professionals. We have been recognized as a "Best Place to Work" for three consecutive years and continue to innovate at the intersection of education and technology.</p>`},{title:`The Future`,content:`<p>Looking ahead, we are investing heavily in AI-powered learning, global expansion, and deepening our enterprise capabilities. Our goal is to reach 1 million learners by 2028 — and you are joining us at the perfect time to help make that happen.</p>`}]),t.text(`<h3>Key Milestones at a Glance</h3><ul><li><b>2018:</b> Company founded, first prototype built</li><li><b>2019:</b> First 10 customers, seed funding raised</li><li><b>2020:</b> 100-customer milestone, remote-first transition</li><li><b>2022:</b> Series B, 300+ customers, international expansion</li><li><b>2024:</b> 500+ customers, AI features launched</li></ul>`)],{desc:`Key milestones and how the company has evolved.`,duration:10})]),r(`Tools & Systems`,[n(`Essential Tools Overview`,`two-col`,[t.text(`<h2>Your Digital Toolkit</h2><p>Here is a quick-reference guide to the tools you will use every day. Bookmark this page — you will refer to it often during your first weeks.</p><h3>Communication</h3><ul><li><b>Slack</b> — Daily chat, team channels, and quick updates</li><li><b>Zoom</b> — Video meetings and virtual collaboration</li><li><b>Email (Gmail/Outlook)</b> — External communication and formal updates</li></ul>`),t.text(`<h3>Productivity & Work</h3><ul><li><b>Notion/Confluence</b> — Documentation, wikis, and meeting notes</li><li><b>Jira/Linear</b> — Task tracking and project management</li><li><b>Google Drive/SharePoint</b> — File storage and document collaboration</li><li><b>Figma/Miro</b> — Design collaboration and whiteboarding</li></ul><h3>HR & Admin</h3><ul><li><b>BambooHR/Workday</b> — Time off, benefits, and personal info</li><li><b>Expensify</b> — Expense reporting and reimbursements</li></ul>`)],{desc:`Quick-reference guide to every tool in the stack.`,duration:10}),n(`Communication & Collaboration Norms`,`accordion`,[t.accordion(`How We Work Together`,[{title:`When to use Slack vs. Email`,content:`<p><b>Slack</b> is for quick questions, team announcements, and informal chat. Expect responses within a few hours. <b>Email</b> is for external contacts, formal documentation, and messages that need a paper trail. Use @mentions sparingly — only when someone specifically needs to see your message.</p>`},{title:`Meeting Etiquette`,content:`<p>Every meeting should have an agenda shared at least 24 hours in advance. Default meeting length is 25 or 50 minutes (not 30/60) to allow transition time. Cameras on by default for team meetings under 5 people. Always end with clear action items and owners.</p>`},{title:`Async-First Culture`,content:`<p>We default to asynchronous communication. This means: document your thinking in writing, share it in a channel, and let people respond on their own schedule. Not everything needs a meeting. Use Loom or short video messages for complex topics that are hard to convey in text.</p>`},{title:`Status & Availability`,content:`<p>Set your Slack status to reflect your availability: "Focusing — slow to respond", "In a meeting", "Offline — back at 2pm". Respect others' status — do not expect instant responses. Use Do Not Disturb during deep work blocks.</p>`},{title:`Giving & Receiving Feedback`,content:`<p>Feedback is a gift. Give it constructively, privately, and with specific examples. Receive it with curiosity, not defensiveness. Our feedback framework: <b>Situation → Behavior → Impact → Request</b>. Practice this in 1:1s and retrospectives.</p>`}]),t.callout(`<p><strong>Remember:</strong> Communication norms exist to reduce friction, not add bureaucracy. When in doubt, over-communicate. No one ever complained about being too informed.</p>`,`tip`)],{desc:`Slack/Teams norms, meeting etiquette, and async communication best practices.`,duration:12}),n(`Setting Up Your Workspace`,`steps`,[t.steps(`Get Set Up in 6 Steps`,[{title:`Step 1: Activate Your Accounts`,content:`<p>Check your email for account activation links. You should receive invites to: company email, Slack, HR system, and project management tools. Complete all activations within your first 24 hours.</p>`},{title:`Step 2: Set Up Your Dev Environment`,content:`<p>Follow the onboarding guide in Notion/Confluence to install required software, clone repositories, and configure your local environment. If you hit any roadblocks, post in the #onboarding-help Slack channel.</p>`},{title:`Step 3: Configure Security & VPN`,content:`<p>Enable two-factor authentication (2FA) on all accounts. Install and connect to the company VPN. Review the security policy — it takes 15 minutes and could save months of headache.</p>`},{title:`Step 4: Set Up Your Physical Workspace`,content:`<p>Whether you are remote or in-office, create a workspace that supports focus and comfort. Ergonomic chair, proper monitor height, good lighting. If you need equipment, submit a request through the HR portal.</p>`},{title:`Step 5: Schedule Your First Week`,content:`<p>Your manager has pre-scheduled key intro meetings. Block out focus time on your calendar — at least 2-3 hours daily for the first month while you ramp up. Protect this time religiously.</p>`},{title:`Step 6: Complete This Onboarding Course`,content:`<p>Finish all modules in this course by the end of your first week. There is a knowledge check at the end — it is not graded, but it helps ensure you have absorbed the key information.</p>`}]),{id:e(),...i(a.laptop,`Organized desk setup with laptop and ergonomic accessories`)}],{desc:`Step-by-step setup instructions for accounts, VPN, and dev environment.`,duration:14})]),r(`Your Role & Team`,[n(`Role Expectations & Success Metrics`,`title-text`,[t.text(`<h2>Your Role & What Success Looks Like</h2><p>Clarity is kindness. Here is exactly what is expected of you and how your performance will be measured.</p><h3>Core Responsibilities</h3><ul><li><b>Primary Function:</b> Execute on your role's key deliverables with quality and consistency</li><li><b>Collaboration:</b> Work cross-functionally with at least 2 other teams</li><li><b>Communication:</b> Provide weekly written updates on progress, blockers, and learnings</li><li><b>Growth:</b> Identify one skill to develop each quarter and create a learning plan</li></ul><h3>Success Metrics (First 90 Days)</h3><ul><li><b>30 days:</b> Complete onboarding, understand team workflows, ship your first contribution</li><li><b>60 days:</b> Own a small project end-to-end, build relationships with key stakeholders</li><li><b>90 days:</b> Lead a medium-sized initiative, mentor a newer team member, contribute to a process improvement</li></ul>`),t.callout(`<p><strong>Your Manager's Commitment:</strong> "I will meet with you weekly for the first 90 days. I will give you honest, timely feedback. I will advocate for your growth. My job is to remove obstacles so you can do your best work."</p>`,`info`)],{desc:`Clear definition of responsibilities, KPIs, and growth path.`,duration:10}),n(`Meet Your Team`,`text-image`,[t.text(`<h2>Your Team & Key Contacts</h2><p>You will be working closely with these people. Here is who they are and what they do:</p><h3>Direct Team</h3><ul><li><b>Your Manager:</b> Your go-to for priorities, feedback, and career development. 1:1s every week.</li><li><b>Team Lead / Senior:</b> Technical or domain expert. Your mentor for day-to-day questions.</li><li><b>Peers:</b> Your fellow team members. Collaborate, pair, and learn from each other.</li></ul><h3>Extended Team</h3><ul><li><b>Product Manager:</b> Defines what we build and why. Your partner in understanding user needs.</li><li><b>Designer:</b> Owns the user experience. Collaborate early and often.</li><li><b>Engineering Manager / Tech Lead:</b> Architectural decisions and technical direction.</li></ul><h3>Support Functions</h3><ul><li><b>HR Business Partner:</b> Benefits, policies, career development resources</li><li><b>IT Support:</b> Tech issues, hardware requests, access problems</li><li><b>Office Manager:</b> Facilities, events, snacks, and office-related needs</li></ul>`),{id:e(),...i(a.onboarding,`Team collaborating around a table in a bright meeting room`)}],{desc:`Team structure, key contacts, and who to go to for what.`,duration:10}),n(`First 90 Days Plan`,`steps`,[t.steps(`Your Roadmap to Success`,[{title:`Week 1: Learn & Connect`,content:`<p>Complete onboarding, set up all tools, attend intro meetings. <b>Goal:</b> Understand the landscape and start building relationships. Schedule 15-minute coffee chats with 5 people outside your immediate team.</p>`},{title:`Week 2-3: Shadow & Absorb`,content:`<p>Shadow team members, sit in on customer calls, read documentation. <b>Goal:</b> Understand how work actually gets done. Take notes on anything confusing — these are opportunities to improve onboarding for the next person.</p>`},{title:`Week 4: First Contribution`,content:`<p>Ship something. It does not have to be big — a bug fix, a documentation update, a process improvement. <b>Goal:</b> Build momentum and demonstrate that you can deliver.</p>`},{title:`Month 2: Own a Project`,content:`<p>Take ownership of a small-to-medium project from start to finish. <b>Goal:</b> Practice autonomy while knowing your team has your back. Present your results at a team meeting.</p>`},{title:`Month 3: Lead & Improve`,content:`<p>Lead a larger initiative. Identify one process or practice that you think could be better and propose an improvement. <b>Goal:</b> Shift from learning mode to contributing mode. Complete your 90-day review with your manager.</p>`}]),t.callout(`<p><strong>Advice from past new hires:</strong> "The first 90 days felt fast. My biggest regret was not asking enough questions in the first month. Everyone expects you to have questions — it is weirder if you do not ask any."</p>`,`tip`)],{desc:`A week-by-week roadmap for the first three months.`,duration:12})])]})},{id:`aidas-selling`,name:`AIDAS Theory of Selling`,description:`Master the proven sales framework: Attention → Interest → Desire → Action → Satisfaction.`,emoji:`💼`,colorIdx:4,tags:`template, sales, AIDAS, selling, business`,getCourse:()=>({name:`AIDAS Sales Mastery`,subtitle:`Master the AIDAS framework — Attention, Interest, Desire, Action, Satisfaction`,description:`<p>Learn and apply the AIDAS sales methodology — a proven five-stage framework for guiding prospects from first contact to loyal customer. Each stage builds on the previous one, creating a natural progression that feels consultative rather than pushy. Includes practical scripts, roleplay scenarios, and assessment tools.</p>`,emoji:`💼`,colorIdx:4,status:`draft`,tags:`template, sales, AIDAS, selling, business`,access:`free`,modules:[r(`The AIDAS Framework`,[n(`What is AIDAS?`,`slide-layout`,[t.text(`<h2>The AIDAS Framework</h2><p>AIDAS is a time-tested sales methodology that breaks the customer journey into five distinct stages:</p><ol><li><b>A — Attention:</b> Capture the prospect's focus in a noisy world</li><li><b>I — Interest:</b> Build genuine curiosity about your solution</li><li><b>D — Desire:</b> Transform interest into a strong want for what you offer</li><li><b>A — Action:</b> Guide the prospect to make a confident buying decision</li><li><b>S — Satisfaction:</b> Ensure post-purchase happiness that drives referrals and repeat business</li></ol><p>Unlike aggressive or scripted approaches, AIDAS is <b>consultative</b> — it aligns the sales process with how people naturally make decisions.</p>`),{id:e(),...i(a.sales,`Professional sales conversation in a modern office setting`)},t.callout(`<p><strong>Key Insight:</strong> Most salespeople spend 80% of their time on Action (closing) while neglecting the first three stages. AIDAS flips this — when you invest in Attention, Interest, and Desire, the Action becomes almost automatic.</p>`,`tip`)],{desc:`Introduction to the five stages: Attention, Interest, Desire, Action, Satisfaction.`,duration:12}),n(`Why AIDAS Works — The Psychology`,`full-text`,[t.text(`<h2>The Psychology Behind Each Stage</h2><p>AIDAS works because it mirrors the <b>natural decision-making process</b> that every human goes through when considering a purchase.</p><h3>Attention — The Reticular Activating System</h3><p>Your brain filters out 99% of sensory information. To break through, your opening must be <b>novel, relevant, or emotionally resonant</b>. Generic openers like "checking in" get filtered out. Specific, insight-driven openers get through.</p><h3>Interest — The Curiosity Gap</h3><p>Humans are wired to seek resolution to unanswered questions. When you share an insight that challenges a prospect's assumptions, you create a <b>curiosity gap</b> — a psychological itch they want to scratch. Interest is not about talking more; it is about asking better questions.</p><h3>Desire — Emotional Decision-Making</h3><p>Neuroscience shows that decisions are made emotionally and justified rationally. Desire is built by connecting your solution to the prospect's <b>aspirations, fears, and identity</b> — not just their logical needs.</p><h3>Action — Reducing Friction</h3><p>The biggest barrier to action is not price — it is <b>uncertainty and perceived risk</b>. Effective Action-stage selling is about removing friction: offering guarantees, providing social proof, and making the next step embarrassingly easy.</p><h3>Satisfaction — The Peak-End Rule</h3><p>People judge an experience by its peak moment and its ending. A strong Satisfaction stage creates a positive ending that colors the entire experience — turning customers into advocates.</p>`)],{desc:`The psychology behind each stage and why this framework outperforms scripted selling.`,duration:12}),n(`AIDAS vs. Other Sales Models`,`tabs`,[t.tabs(`Compare Sales Frameworks`,[{title:`AIDAS`,content:`<p><b>Stages:</b> Attention → Interest → Desire → Action → Satisfaction<br><b>Best for:</b> Consultative B2B sales, high-ticket items, relationship-based selling<br><b>Key strength:</b> Covers the full lifecycle including post-sale satisfaction — most frameworks stop at close.<br><b>Weakness:</b> Requires patience and genuine curiosity — not suited for high-volume transactional sales.</p>`},{title:`SPIN Selling`,content:`<p><b>Stages:</b> Situation → Problem → Implication → Need-Payoff<br><b>Best for:</b> Complex B2B sales with long cycles<br><b>Key strength:</b> Deep discovery through structured questioning.<br><b>Weakness:</b> Can feel like an interrogation if not done skillfully; less focus on emotional drivers.</p>`},{title:`Challenger Sale`,content:`<p><b>Approach:</b> Teach → Tailor → Take Control<br><b>Best for:</b> Disruptive solutions where the prospect does not know what they do not know<br><b>Key strength:</b> Positions you as a trusted advisor who brings new insights.<br><b>Weakness:</b> High bar for industry knowledge; can come across as arrogant if poorly executed.</p>`},{title:`Sandler Method`,content:`<p><b>Approach:</b> Up-front contract, pain-focused discovery, negative reverse selling<br><b>Best for:</b> Professional services, consulting<br><b>Key strength:</b> Qualifies hard early — you disqualify bad-fit prospects quickly.<br><b>Weakness:</b> Techniques like negative reverse can feel manipulative to modern buyers.</p>`}]),t.callout(`<p><strong>Why AIDAS wins for modern selling:</strong> It balances structure with authenticity. The Satisfaction stage is a differentiator — most frameworks ignore what happens after the close, but repeat business and referrals are where the real revenue lives.</p>`,`info`)],{desc:`Compare AIDAS with SPIN, Challenger, and Sandler methodologies.`,duration:10})]),r(`Stage 1 & 2: Attention & Interest`,[n(`Capturing Attention`,`slide-layout`,[t.text(`<h2>Breaking Through the Noise</h2><p>Your prospects are bombarded with hundreds of messages daily. To earn their attention, your outreach must be <b>relevant, specific, and insight-driven</b>.</p><h3>Effective Attention Hooks</h3><ul><li><b>The Insight Hook:</b> "I noticed your team recently [specific observation]. Companies in your space typically struggle with [relevant challenge]."</li><li><b>The Question Hook:</b> "What if you could reduce [pain point] by 40% without changing your current workflow?"</li><li><b>The Referral Hook:</b> "[Mutual connection] suggested I reach out. They thought our conversation about [topic] would be relevant to you."</li></ul><h3>Avoid These Attention-Killers</h3><ul><li>❌ "Just checking in…"</li><li>❌ "Hope this email finds you well."</li><li>❌ Leading with your product features before establishing context</li></ul>`),{id:e(),...i(a.meeting,`Two professionals engaged in a focused business conversation`)},t.callout(`<p><strong>Pro Tip:</strong> Research your prospect for 5 minutes before any outreach. Find one specific, relevant detail about their company, role, or industry. Personalization beats templated outreach by 4x in response rates.</p>`,`tip`)],{desc:`Opening hooks, cold outreach templates, and first-impression techniques.`,duration:14}),n(`Building Genuine Interest`,`media-guide`,[t.video(o(`N9cl5VDE5xU`),`Sales training: Building genuine interest through discovery`),t.text(`<h2>From Attention to Interest</h2><p>Attention gets you in the door. Interest keeps you there. The bridge between them is <b>discovery</b> — the art of asking questions that reveal what the prospect truly cares about.</p><h3>The Discovery Framework</h3><ol><li><b>Context Questions:</b> "Tell me about your current process for [relevant area]."</li><li><b>Impact Questions:</b> "What happens when that process breaks down?"</li><li><b>Vision Questions:</b> "If you could wave a magic wand, what would the ideal solution look like?"</li><li><b>Constraint Questions:</b> "What has stopped you from solving this before?"</li></ol><h3>Active Listening Techniques</h3><ul><li><b>Labeling:</b> "It sounds like [observation] is a major frustration."</li><li><b>Mirroring:</b> Repeat the last 1-3 words of their sentence as a question — it invites elaboration.</li><li><b>Pausing:</b> After they finish speaking, count to 3 before responding. The silence draws out deeper insights.</li></ul>`),t.callout(`<p><strong>Remember:</strong> The prospect should be talking 70% of the time during the Interest stage. If you are doing most of the talking, you are pitching, not discovering.</p>`,`warning`)],{desc:`Discovery questions, active listening, and tailoring your pitch.`,duration:15}),n(`Attention & Interest: Practice`,`quiz-focus`,[t.text(`<h2>Knowledge Check: Stages 1 & 2</h2><p>Test your understanding of the Attention and Interest stages before moving on to Desire and Action.</p>`),t.quiz([{q:`Which of the following is the most effective attention hook?`,subtype:`multiple-choice`,options:[`"Just checking in to see if you had time to review my proposal."`,`"I noticed your company just expanded into Europe. Most firms at this stage struggle with cross-border compliance — is that on your radar?"`,`"Hope this email finds you well. I wanted to introduce our product..."`,`"Following up for the third time on my previous message."`],correct:1},{q:`During the Interest stage, the prospect should be talking roughly 70% of the time.`,subtype:`true-false`,correct:0},{q:`The technique of repeating the last few words of someone's sentence as a question to invite elaboration is called _______.`,subtype:`fill-blank`,correct:`mirroring`},{q:`What is the "curiosity gap" in the context of building interest?`,subtype:`multiple-choice`,options:[`The physical distance between you and the prospect`,`A psychological itch created when you share an insight that challenges assumptions`,`The time between initial contact and first meeting`,`The difference between your price and their budget`],correct:1}])],{desc:`Roleplay scenarios and a knowledge check on stages 1-2.`,duration:10})]),r(`Stage 3 & 4: Desire & Action`,[n(`Creating Desire`,`text-image`,[t.text(`<h2>Transforming Interest into Desire</h2><p>Interest is intellectual. <b>Desire is emotional.</b> Your job at this stage is to connect your solution to what the prospect <em>feels</em> — their aspirations, frustrations, fears, and identity.</p><h3>Techniques for Building Desire</h3><ul><li><b>Future-Pacing:</b> "Imagine it is six months from now and this problem is solved. What does your day look like?" Help them vividly picture the after-state.</li><li><b>Contrast Framing:</b> "Right now, your team spends 10 hours a week on manual reporting. With this solution, that drops to 30 minutes. What would your team do with those extra 9.5 hours?"</li><li><b>Social Proof:</b> "Your competitor [name] implemented this last year. They saw a 35% improvement in their close rate within the first quarter."</li><li><b>Loss Aversion:</b> "The cost of inaction is not just the status quo — it is falling behind while competitors move ahead."</li></ul>`),{id:e(),...i(a.presentation,`A compelling business presentation with engaging visuals`)}],{desc:`Pain-point mapping, value prop articulation, and emotional drivers.`,duration:14}),n(`Driving Action — Closing with Confidence`,`steps`,[t.steps(`The Action Stage: From Maybe to Yes`,[{title:`Step 1: Summarize Value`,content:`<p>Recap the specific value you will deliver, in their words. "You mentioned that solving [problem] would save your team [X] hours and accelerate [initiative]. Our solution delivers exactly that by [mechanism]."</p>`},{title:`Step 2: Address Objections Proactively`,content:`<p>Surface concerns before they do. "Some clients wonder about the implementation timeline. Here is how we handle that…" This demonstrates confidence and removes the prospect's need to play devil's advocate.</p>`},{title:`Step 3: Present Clear Options`,content:`<p>Offer 2-3 clear paths forward — never a binary yes/no. "Most clients start with Option A (our core package) or Option B (which includes premium support). Which feels like the better fit?"</p>`},{title:`Step 4: Make the Next Step Easy`,content:`<p>Reduce friction to near-zero. "I have a draft agreement ready. Would Tuesday or Thursday work better for a 20-minute review call to finalize details?"</p>`},{title:`Step 5: Confirm and Reassure`,content:`<p>After the yes, reinforce their decision. "Great choice — you are going to see results quickly. I will personally oversee the onboarding to make sure everything goes smoothly."</p>`}]),t.callout(`<p><strong>Closing Mindset Shift:</strong> You are not "closing" a prospect — you are <em>opening a relationship</em>. The best salespeople view the close as the beginning, not the end.</p>`,`info`)],{desc:`Closing techniques, objection handling, and call-to-action strategies.`,duration:15}),n(`Desire & Action: Practice`,`assessment`,[t.text(`<h2>Scenario-Based Assessment</h2><p>Apply what you have learned about the Desire and Action stages to these realistic scenarios.</p>`),t.quiz([{q:`A prospect says: "This looks great, but I need to think about it." Which response best drives action?`,subtype:`multiple-choice`,options:[`"No problem, take your time. I will follow up next month."`,`"I completely understand. What specifically do you need to think through? Maybe I can help clarify those points right now."`,`"If you do not decide today, the price goes up tomorrow."`,`"Ok, let me know when you are ready."`],correct:1},{q:`Loss aversion is about showing prospects what they gain by buying your product.`,subtype:`true-false`,correct:1},{q:`When presenting options during the Action stage, you should always offer a binary _______ choice.`,subtype:`fill-blank`,correct:`yes/no`},{q:`Which technique involves helping the prospect vividly imagine their life after the problem is solved?`,subtype:`multiple-choice`,options:[`Contrast framing`,`Future-pacing`,`Mirroring`,`Labeling`],correct:1}])],{desc:`Scenarios to practice moving prospects from desire to commitment.`,duration:10})]),r(`Stage 5: Satisfaction & Beyond`,[n(`Ensuring Customer Satisfaction`,`callout`,[t.text(`<h2>The Satisfaction Stage — Where Revenue Multiplies</h2><p>The Satisfaction stage is where a one-time buyer becomes a <b>lifetime customer</b> and a source of referrals. Most salespeople disappear after the close — which is exactly when the relationship matters most.</p>`),t.callout(`<p><strong>Immediate Post-Sale (First 48 Hours):</strong> Send a personalized thank-you message. Introduce them to their dedicated onboarding contact. Set expectations for the first week. <em>Silence after the sale creates buyer's remorse.</em></p>`,`tip`),t.callout(`<p><strong>First Week:</strong> Check in proactively. "How is your first week going? Anything I can clarify?" This single touchpoint reduces early churn by 30%.</p>`,`info`),t.callout(`<p><strong>First Month:</strong> Schedule a value review. Show them measurable progress toward their goals. If results are not yet visible, explain the timeline and what to expect.</p>`,`info`),t.callout(`<p><strong>Ongoing:</strong> Check in quarterly — not to sell, but to help. Share relevant articles, introduce them to useful contacts, and celebrate their wins publicly (with permission).</p>`,`tip`)],{desc:`Post-sale follow-up, onboarding, and setting the stage for retention.`,duration:10}),n(`Referrals & Repeat Business`,`title-text`,[t.text(`<h2>Turning Satisfaction into Growth</h2><p>Satisfied customers are your best source of new business. But referrals do not happen automatically — you need a system.</p><h3>The Referral Engine</h3><ol><li><b>Earn the right to ask:</b> Only request referrals after delivering measurable value. If you have not made a positive impact, asking for referrals damages trust.</li><li><b>Make it specific:</b> "Who is the one person in your network who is dealing with [specific problem] right now?" is far more effective than "Do you know anyone who might be interested?"</li><li><b>Make it easy:</b> Offer to draft a warm introduction email they can forward. Reduce their effort to near-zero.</li><li><b>Close the loop:</b> Always thank the referrer and update them on the outcome. This reinforces the behavior and leads to more referrals.</li></ol><h3>Expanding Existing Accounts</h3><ul><li>Conduct quarterly business reviews to identify unmet needs</li><li>Share case studies of how similar customers expanded their usage</li><li>Introduce new features or services as solutions to evolving challenges</li></ul>`)],{desc:`Turning satisfaction into advocacy and recurring revenue.`,duration:10}),n(`Full AIDAS Roleplay & Final Assessment`,`video-quiz`,[t.video(o(`h7TlXJKyHSQ`),`Full AIDAS sales conversation: from introduction to close`),t.text(`<h2>End-to-End AIDAS Roleplay</h2><p>Watch the full sales conversation above. Pay attention to how the salesperson transitions through each AIDAS stage naturally — the framework should feel invisible to the prospect.</p>`),t.quiz([{q:`In the video, how does the salesperson first capture Attention?`,subtype:`multiple-choice`,options:[`By introducing their product features`,`By referencing a specific insight about the prospect's industry`,`By offering a discount`,`By mentioning their company's awards`],correct:1},{q:`The Satisfaction stage is optional — most revenue comes from new customer acquisition.`,subtype:`true-false`,correct:1},{q:`Post-sale, the most critical window for preventing buyer's remorse is the first _______ hours.`,subtype:`fill-blank`,correct:`48`},{q:`What is the best time to ask for a referral?`,subtype:`multiple-choice`,options:[`Immediately after the sale closes`,`After delivering measurable value to the customer`,`During the first meeting`,`Never — referrals should happen organically`],correct:1},{q:`Match each AIDAS stage with its primary goal:`,subtype:`matching`,pairs:[{left:`Attention`,right:`Break through the noise`},{left:`Interest`,right:`Build genuine curiosity`},{left:`Desire`,right:`Connect emotionally`},{left:`Action`,right:`Make the decision easy`},{left:`Satisfaction`,right:`Create advocates`}]}])],{desc:`End-to-end roleplay scenario covering all five stages.`,duration:15})])]})},{id:`present-company`,name:`Present a Company`,description:`A polished company overview: mission, products, team, culture, and competitive advantage.`,emoji:`🏢`,colorIdx:3,tags:`template, company, presentation, about, pitch`,getCourse:()=>({name:`Our Company Story`,subtitle:`A complete overview of who we are, what we do, and why it matters`,description:`<p>A polished, shareable company presentation covering mission, products, team, culture, and market position. Perfect for new hires, investors, partners, and customers who want to understand the full picture of our organization.</p>`,emoji:`🏢`,colorIdx:3,status:`draft`,tags:`template, company, presentation, about, pitch`,access:`free`,modules:[r(`Who We Are`,[n(`Our Mission & Vision`,`slide-layout`,[t.text(`<h2>Our Reason for Being</h2><p>Every company starts with a problem worth solving. Here is ours — and why it matters.</p><h3>The Problem We Solve</h3><p>Organizations struggle to create, deliver, and track effective training at scale. Traditional methods are slow, expensive, and disconnected from how modern teams actually learn. We exist to close that gap.</p><h3>Our Mission</h3><p>To <b>democratize world-class training</b> by making it fast to create, engaging to experience, and easy to measure — for organizations of every size.</p><h3>Our Vision</h3><p>A future where every team member, regardless of their role or location, has access to the knowledge and skills they need to thrive.</p>`),{id:e(),...i(a.company,`Modern company headquarters with collaborative workspaces`)},t.callout(`<p><strong>Why this matters now:</strong> The global shift to hybrid work and AI-augmented roles has made traditional training obsolete. Organizations that cannot adapt their learning strategies will fall behind — fast.</p>`,`info`)],{desc:`The problem we solve and the future we are building toward.`,duration:10}),n(`Our Story`,`text-image`,[t.text(`<h2>From Idea to Impact</h2><p>Our journey began with a simple observation: creating effective training content took too long, cost too much, and rarely engaged learners the way it should.</p><h3>The Founding Story</h3><p>In 2018, our founders — a former educator and a software engineer — spent six months interviewing over 200 learning and development professionals. The message was consistent: <b>"We know what good training looks like, but we cannot produce it fast enough."</b></p><p>They set out to build a platform that would reduce course creation time from weeks to hours, without sacrificing quality. The first prototype was rough — but the idea resonated. Within three months of launch, they had their first 10 paying customers.</p>`),{id:e(),...i(a.learning,`Team collaborating on educational content creation`)}],{desc:`Founding story, key milestones, and growth trajectory.`,duration:12}),n(`Leadership Team`,`two-col`,[t.text(`<h2>Meet Our Leaders</h2><h3>Executive Team</h3><ul><li><b>CEO & Co-Founder:</b> Former educator with 15 years in EdTech. Drives vision and strategy.</li><li><b>CTO & Co-Founder:</b> 12 years building SaaS platforms. Leads engineering and AI initiatives.</li><li><b>COO:</b> 20 years in operations at Fortune 500 companies. Ensures we deliver reliably at scale.</li></ul>`),t.text(`<h3>Extended Leadership</h3><ul><li><b>VP of Product:</b> 10 years in product leadership. Obsessed with user experience.</li><li><b>VP of Sales:</b> Built sales teams at three successful startups. Customer-first approach.</li><li><b>VP of Customer Success:</b> Former teacher turned customer advocate. Ensures every client thrives.</li><li><b>VP of Marketing:</b> Brand storyteller with experience across B2B and B2C.</li><li><b>VP of People:</b> 15 years in HR leadership. Building a culture where everyone belongs.</li></ul>`)],{desc:`Meet the people driving the vision forward.`,duration:8})]),r(`What We Do`,[n(`Products & Services`,`text-image`,[t.text(`<h2>What We Build</h2><p>Our platform is designed around three core capabilities that work together seamlessly:</p><h3>1. AI-Powered Course Authoring</h3><p>Create full courses in minutes — not weeks. Describe your topic, and our AI generates outlines, content blocks, quizzes, and even images. Then fine-tune everything in our live editor.</p><h3>2. Engaging Learner Experience</h3><p>Deliver training through a modern, mobile-responsive player that supports video, interactive quizzes, scenario-based learning, and progress tracking. Learners actually <em>enjoy</em> using it.</p><h3>3. Analytics & Insights</h3><p>See exactly how learners engage with your content. Track completion rates, quiz performance, drop-off points, and time spent — all in real-time dashboards.</p>`),{id:e(),...i(a.productivity,`Dashboard displaying analytics and course metrics`)}],{desc:`Overview of each product line, key features, and customer value.`,duration:12}),n(`How We Deliver Value`,`tabs`,[t.tabs(`What Sets Us Apart`,[{title:`Speed`,content:`<p><b>Traditional tools:</b> 4-6 weeks to create a 1-hour course.<br><b>Our platform:</b> 1-2 hours with AI assistance, or a few days for a fully customized course. That is a <b>20x speed improvement</b>. Customers tell us this is the single biggest reason they chose us.</p>`},{title:`Quality`,content:`<p>Speed means nothing without quality. Our AI is trained on instructional design best practices and produces content that follows proven pedagogical patterns. Every course includes varied block types, assessments, and engagement hooks — not just walls of text.</p>`},{title:`Flexibility`,content:`<p>Start with AI, finish with full manual control. Our editor gives you pixel-level control over every block. Swap templates, add custom HTML, embed third-party content, and brand everything to match your organization.</p>`},{title:`Scale`,content:`<p>From 10 learners to 100,000 — our platform handles it. Enterprise SSO, SCORM/xAPI export, API access, and white-label options make us the choice for organizations that need to grow without switching tools.</p>`}]),t.callout(`<p><strong>Customer quote:</strong> "We evaluated six platforms. Yours was the only one that did not force us to choose between speed and quality." — Learning Director, Fortune 500 Company</p>`,`info`)],{desc:`Side-by-side competitive comparison and unique differentiators.`,duration:10}),n(`Customer Success Stories`,`accordion`,[t.accordion(`Real Results from Real Customers`,[{title:`Global Tech Company — 40% Faster Onboarding`,content:`<p>A multinational tech company with 12,000 employees used our platform to rebuild their new-hire onboarding. Results after 6 months: <b>40% reduction in time-to-productivity</b> for new engineers, 92% learner satisfaction score, and 3,500 hours saved annually by automating content updates.</p>`},{title:`Healthcare Network — Compliance Training at Scale`,content:`<p>A network of 45 hospitals needed to train 18,000 staff on updated compliance procedures within 60 days. Using our AI authoring, they created 12 courses in under 2 weeks. <b>99.7% completion rate</b> within the deadline — and they passed their regulatory audit with zero findings.</p>`},{title:`Retail Chain — Sales Training Transformation`,content:`<p>A 500-store retail chain replaced their in-person sales training with our platform. Results: <b>23% increase in average transaction value</b>, training costs reduced by 60%, and consistent training quality across all locations for the first time.</p>`}])],{desc:`Real customer testimonials and case studies.`,duration:10})]),r(`Why Choose Us`,[n(`Our Culture & Values`,`full-text`,[t.text(`<h2>What It Is Like to Work Here</h2><p>Culture is not about ping-pong tables and free snacks. It is about how we treat each other, how we make decisions, and what we reward.</p><h3>Our Culture in Practice</h3><ul><li><b>Transparency:</b> All-hands meetings every month where leadership shares real numbers — revenue, challenges, and strategic decisions. No sugar-coating.</li><li><b>Autonomy:</b> We hire great people and trust them to make great decisions. No micromanagement. Clear goals, flexible paths.</li><li><b>Continuous Learning:</b> Every team member gets an annual learning stipend plus dedicated time for professional development.</li><li><b>Inclusion:</b> Diverse teams make better decisions. We actively work to build a team that reflects the customers we serve.</li><li><b>Work-Life Integration:</b> We measure output, not hours. Take the time you need — we trust you to deliver.</li></ul>`)],{desc:`What it is like to work here, diversity & inclusion, and community impact.`,duration:10}),n(`Market Position & Growth`,`timeline`,[t.timeline(`Our Growth Trajectory`,[{title:`2024`,content:`<p><b>500+ customers</b> across 18 countries. Launched AI-powered course generation. Recognized in G2's Top 10 LMS platforms. Team grew to 200.</p>`},{title:`2023`,content:`<p><b>Series B funding:</b> $25M to accelerate AI and enterprise features. Opened European office. Reached 300 customers.</p>`},{title:`2022`,content:`<p><b>Enterprise launch:</b> SSO, SCORM export, white-label. Crossed the 100-customer milestone. Team grew to 75.</p>`},{title:`2021`,content:`<p><b>Remote-first transition:</b> Permanently adopted a remote-first model. Launched marketplace for course templates. Revenue grew 3x.</p>`},{title:`2020`,content:`<p><b>Pandemic pivot:</b> Helped 50+ organizations transition to digital training within weeks. Launched live collaboration features.</p>`}]),t.callout(`<p><strong>Looking Ahead:</strong> We are investing in AI-powered personalization, global expansion into APAC, and deeper integrations with the tools our customers already use — all while maintaining the speed and simplicity that got us here.</p>`,`info`)],{desc:`Industry trends, market share, and strategic direction.`,duration:10}),n(`Partner With Us`,`slide-layout`,[t.text(`<h2>Let's Build the Future Together</h2><p>Whether you are a potential customer, investor, partner, or future team member — we would love to hear from you.</p><h3>For Customers</h3><p>Ready to transform how your organization learns? Start with a free trial and see the difference AI-powered course creation makes. No credit card required.</p><h3>For Investors</h3><p>We are backed by top-tier VCs and are always open to conversations with value-aligned partners who share our vision for the future of learning.</p><h3>For Partners</h3><p>We collaborate with content creators, training consultancies, and technology platforms to expand our ecosystem. If you have an idea for a partnership, let us talk.</p><h3>For Future Team Members</h3><p>We are always looking for curious, driven people who want to make a real impact. Check our careers page for current openings.</p>`),{id:e(),...i(a.team,`Diverse team celebrating a milestone together`)},t.callout(`<p><strong>Next Step:</strong> Visit our website, schedule a demo, or send us an email. We respond to every inquiry within one business day.</p>`,`tip`)],{desc:`Next steps for customers, investors, and partners.`,duration:8})])]})},{id:`remote-working`,name:`Remote Working Tips`,description:`Best practices for productive, healthy, and connected remote work — tools, routines, and well-being.`,emoji:`🏠`,colorIdx:5,tags:`template, remote, wfh, productivity, wellness`,getCourse:()=>({name:`Remote Work Success`,subtitle:`Master the art of productive, balanced, and connected remote work`,description:`<p>Practical strategies for thriving in a remote or hybrid work environment. Covers workspace setup, time management, digital communication, mental well-being, and career growth from anywhere. Based on research from remote-first companies and productivity science.</p>`,emoji:`🏠`,colorIdx:5,status:`draft`,tags:`template, remote, wfh, productivity, wellness`,access:`free`,modules:[r(`Setting Up for Success`,[n(`Your Ideal Home Workspace`,`text-image`,[t.text(`<h2>Design Your Workspace for Focus</h2><p>Your environment shapes your behavior. A well-designed workspace boosts productivity, reduces fatigue, and signals to your brain that it is <b>time to focus</b>.</p><h3>Ergonomics Checklist</h3><ul><li><b>Monitor:</b> Top of screen at eye level, arm's length away. Use a laptop stand or external monitor — looking down at a laptop strains your neck.</li><li><b>Chair:</b> Feet flat on the floor, knees at 90°, lower back supported. If you do not have an ergonomic chair, use a cushion for lumbar support.</li><li><b>Keyboard & Mouse:</b> Wrists straight, elbows at 90°. Consider a split keyboard if you type extensively.</li><li><b>Lighting:</b> Natural light is best. Position your desk perpendicular to windows to reduce glare. Use a 5000K daylight bulb for task lighting.</li></ul>`),{id:e(),...i(a.remote,`Well-organized home office with ergonomic setup and plants`)}],{desc:`Ergonomics, lighting, desk setup, and creating a focus zone.`,duration:10}),n(`Essential Remote Tools`,`two-col`,[t.text(`<h2>Your Remote Work Toolkit</h2><p>The right tools make remote work seamless. Here is what every remote worker needs:</p><h3>Communication</h3><ul><li><b>Slack / Microsoft Teams:</b> Daily chat and quick collaboration</li><li><b>Zoom / Google Meet:</b> Video calls with reliable screen sharing</li><li><b>Loom:</b> Record quick video messages instead of scheduling meetings</li></ul><h3>Project Management</h3><ul><li><b>Notion / Confluence:</b> Documentation and wikis</li><li><b>Jira / Linear / Asana:</b> Task and project tracking</li></ul>`),t.text(`<h3>Focus & Productivity</h3><ul><li><b>Focusmate / Flow Club:</b> Virtual co-working for accountability</li><li><b>RescueTime / Toggl:</b> Track where your time actually goes</li><li><b>Freedom / Cold Turkey:</b> Block distracting websites during deep work</li></ul><h3>Collaboration</h3><ul><li><b>Figma / Miro:</b> Visual collaboration and whiteboarding</li><li><b>Google Workspace / Office 365:</b> Real-time document collaboration</li><li><b>GitHub / GitLab:</b> Code collaboration and version control</li></ul>`)],{desc:`Communication, project management, and collaboration tools overview.`,duration:10}),n(`Internet & Tech Reliability`,`callout`,[t.text(`<h2>Stay Connected, No Matter What</h2><p>Your internet connection is your lifeline. Here is how to ensure it never lets you down during an important meeting:</p>`),t.callout(`<p><strong>Internet Setup:</strong> Use a wired Ethernet connection whenever possible. Wi-Fi is convenient but less stable. If you must use Wi-Fi, position your router centrally and consider a mesh network for larger homes.</p>`,`tip`),t.callout(`<p><strong>Backup Plan:</strong> Keep your phone's hotspot configured and tested. Know how to switch to it in under 30 seconds. For critical presentations, have a backup device ready.</p>`,`warning`),t.callout(`<p><strong>VPN & Security:</strong> Always use your company VPN when accessing internal systems. Keep your router firmware updated. Use a password manager — remote workers are targeted by cyberattacks 3x more than office workers.</p>`,`danger`),t.callout(`<p><strong>Hardware Essentials:</strong> External monitor (24" minimum), dedicated webcam, noise-canceling headphones with a quality microphone, and a UPS (uninterruptible power supply) if you live in an area with frequent outages.</p>`,`info`)],{desc:`Backup plans, VPN, security basics, and hardware recommendations.`,duration:10})]),r(`Productivity & Routines`,[n(`Designing Your Daily Routine`,`steps`,[t.steps(`Build a Routine That Works`,[{title:`Step 1: Morning Ritual`,content:`<p>Start your day with intention — not your inbox. Spend the first 30 minutes on something that energizes you: exercise, reading, meditation, or a hobby. <b>Do not check email or Slack until your morning ritual is complete.</b></p>`},{title:`Step 2: Define Your MITs`,content:`<p>Identify your <b>Most Important Tasks</b> for the day — no more than 3. Write them down before you open any communication tools. These are your non-negotiables for the day.</p>`},{title:`Step 3: Time Block Your Calendar`,content:`<p>Block 2-4 hours of uninterrupted deep work time. Mark it as "busy" on your calendar. Treat this time as sacred — no meetings, no Slack, no email. This is when your best work happens.</p>`},{title:`Step 4: Batch Shallow Work`,content:`<p>Group emails, messages, and administrative tasks into 1-2 dedicated blocks (e.g., 11:00-11:30 AM and 4:00-4:30 PM). Outside these blocks, close your email and mute notifications.</p>`},{title:`Step 5: End-of-Day Shutdown Ritual`,content:`<p>Review what you accomplished, update your task list for tomorrow, and <b>explicitly close your work apps</b>. This ritual tells your brain "work is done" and helps prevent burnout.</p>`}]),t.callout(`<p><strong>Research Insight:</strong> Knowledge workers average only 2 hours and 48 minutes of productive time per day. A structured routine can double your productive output without working longer hours.</p>`,`tip`)],{desc:`Morning rituals, time blocking, deep work vs. shallow work.`,duration:12}),n(`Avoiding Distractions at Home`,`accordion`,[t.accordion(`Common Distractions & How to Handle Them`,[{title:`Household Noise`,content:`<p>Use noise-canceling headphones. Communicate your work schedule to family or housemates — a simple "Do Not Disturb" sign on your door works surprisingly well. Schedule focused work during quiet hours (early morning or late evening if needed).</p>`},{title:`Phone Notifications`,content:`<p>Put your phone in another room during deep work blocks. Enable Focus Mode (iOS) or Do Not Disturb (Android). The average person checks their phone 96 times a day — each interruption costs 23 minutes to fully regain focus.</p>`},{title:`Household Chores`,content:`<p>Seeing a messy kitchen while working is distracting. Tidy up before you start work, or designate chore time during breaks. Do not fall into the trap of "I will just quickly do the dishes" — it fragments your focus.</p>`},{title:`Social Media & News`,content:`<p>Use website blockers during work hours. Schedule a specific time (e.g., lunch break) for catching up on news and social media. The infinite scroll is designed to keep you engaged — do not fight willpower; use tools.</p>`},{title:`Children & Family`,content:`<p>If you have young children at home, coordinate with a partner or caregiver to create uninterrupted blocks. Be realistic — you may need to work split shifts (early morning + evening) to accommodate family needs. Communicate this schedule clearly with your team.</p>`}])],{desc:`Common distractions and how to manage them.`,duration:12}),n(`Async vs. Sync Communication`,`tabs`,[t.tabs(`Choose the Right Mode`,[{title:`Async (Default)`,content:`<p><b>Best for:</b> Status updates, documentation, detailed proposals, feedback on written work, anything that does not require an immediate response.<br><b>Tools:</b> Slack messages (with expectation of 2-4 hour response), Notion docs, Loom videos, email.<br><b>Why it matters:</b> Async respects everyone's time zone and deep work schedule. It creates a written record. It forces clarity — you cannot ramble in writing the way you can in a meeting.</p>`},{title:`Sync (Intentional)`,content:`<p><b>Best for:</b> Brainstorming, difficult conversations, relationship building, complex problem-solving that requires real-time back-and-forth.<br><b>Tools:</b> Zoom/Meet with an agenda shared in advance.<br><b>Rule of thumb:</b> If a conversation goes beyond 5 back-and-forth Slack messages, switch to a quick call. If three or more people need to be involved, schedule a meeting — but keep it to 25 minutes with a clear agenda.</p>`}]),t.callout(`<p><strong>Default to async.</strong> Before scheduling a meeting, ask: "Could this be a document, a Loom video, or a Slack thread instead?" You will be surprised how often the answer is yes.</p>`,`info`)],{desc:`When to use email, chat, video calls, or async docs.`,duration:10})]),r(`Well-Being & Connection`,[n(`Preventing Burnout`,`title-text`,[t.text(`<h2>Protect Your Energy</h2><p>Remote work blurs the line between work and life. Without intentional boundaries, you risk <b>burnout</b> — a state of emotional, physical, and mental exhaustion caused by prolonged stress.</p><h3>Warning Signs of Burnout</h3><ul><li>Dreading work that you used to enjoy</li><li>Feeling exhausted even after a full night's sleep</li><li>Irritability with colleagues or family</li><li>Difficulty concentrating on tasks that used to be easy</li><li>Physical symptoms: headaches, muscle tension, changes in appetite</li></ul><h3>Prevention Strategies</h3><ul><li><b>Set hard boundaries:</b> Define a shutdown time and stick to it. No "just one more email" at 9 PM.</li><li><b>Take real breaks:</b> A 5-minute walk is better than 5 minutes of scrolling social media. Move your body.</li><li><b>Use your PTO:</b> 55% of remote workers do not use all their vacation days. Take time off — your brain needs it.</li><li><b>Stay social:</b> Loneliness is a top complaint among remote workers. Schedule virtual coffee chats and in-person meetups when possible.</li></ul>`),t.callout(`<p><strong>If you are struggling:</strong> Talk to your manager. Most companies have mental health resources, EAP programs, or flexible arrangements. Suffering in silence helps no one.</p>`,`warning`)],{desc:`Boundary-setting, breaks, exercise, and knowing when to log off.`,duration:10}),n(`Staying Connected While Remote`,`full-text`,[t.text(`<h2>Fight the Isolation Trap</h2><p>Remote work can be lonely. Without intentional effort, you can go days without a meaningful conversation with a colleague. Here is how to stay connected:</p><h3>Build Connection Rituals</h3><ul><li><b>Virtual Coffee Chats:</b> Schedule a 15-minute informal chat with a different colleague each week. No agenda — just connect as humans.</li><li><b>Team Rituals:</b> Weekly show-and-tell, Friday wins channel, or a "watercooler" Slack channel where people share non-work stuff (pets, hobbies, weekend plans).</li><li><b>Co-Working Sessions:</b> Join a virtual co-working session where everyone works on their own tasks but shares the space. It recreates the "ambient presence" of an office.</li><li><b>In-Person Meetups:</b> If your team is distributed, aim for at least one in-person gathering per year. The relationship ROI is enormous.</li><li><b>Celebrate Wins Publicly:</b> Use a #wins or #kudos channel to recognize colleagues. Public appreciation is one of the strongest predictors of team satisfaction.</li></ul>`)],{desc:`Virtual coffee chats, team rituals, and combating isolation.`,duration:10}),n(`Remote Work Self-Assessment`,`assessment`,[t.text(`<h2>How Remote-Ready Are You?</h2><p>Take this self-assessment to identify your strengths and areas for improvement as a remote worker.</p>`),t.quiz([{q:`Which of the following is the most effective way to start your workday?`,subtype:`multiple-choice`,options:[`Check email and Slack immediately to see what you missed`,`Complete a morning ritual (exercise, reading, etc.) before opening any work apps`,`Jump straight into your hardest task with no transition`,`Scroll through social media until you feel ready to work`],correct:1},{q:`Taking breaks during the workday reduces productivity.`,subtype:`true-false`,correct:1},{q:`The average person checks their phone about _______ times per day.`,subtype:`fill-blank`,correct:`96`},{q:`What is the recommended approach for handling email and messages?`,subtype:`multiple-choice`,options:[`Respond to every notification immediately to stay on top of things`,`Batch email and message processing into 1-2 dedicated time blocks per day`,`Only check email once a week`,`Have an assistant handle all your communications`],correct:1},{q:`Which is a warning sign of burnout?`,subtype:`multiple-choice`,options:[`Feeling excited about challenging projects`,`Dreading work you used to enjoy`,`Taking regular vacation days`,`Having clear boundaries between work and life`],correct:1}])],{desc:`Self-assessment: how remote-ready are you?`,duration:8})])]})},{id:`cybersecurity-101`,name:`Cybersecurity 101`,description:`Essential security awareness: phishing, passwords, data protection, and safe browsing habits.`,emoji:`🔒`,colorIdx:2,tags:`template, security, cybersecurity, phishing, awareness`,getCourse:()=>({name:`Cybersecurity Essentials`,subtitle:`Protect yourself and your organization from common cyber threats`,description:`<p>A practical cybersecurity awareness course for everyone — not just IT. Learn to spot phishing, create strong passwords, protect sensitive data, and build security-first habits at work and home. Real-world examples and hands-on activities throughout.</p>`,emoji:`🔒`,colorIdx:2,status:`draft`,tags:`template, security, cybersecurity, phishing, awareness`,access:`free`,modules:[r(`Understanding the Threat Landscape`,[n(`Why Cybersecurity Matters`,`slide-layout`,[t.text(`<h2>It Is Not Just an IT Problem</h2><p>Cybersecurity is everyone's responsibility. In 2024 alone, <b>cybercrime cost the global economy over $9.5 trillion</b>. The majority of successful attacks start with a single human error — a clicked link, a weak password, or a moment of misplaced trust.</p><h3>Why You Are a Target</h3><ul><li><b>Attackers go for the weakest link:</b> They do not hack systems — they hack people. 74% of breaches involve the human element.</li><li><b>Your credentials are valuable:</b> A single set of login credentials sells for $50-$500 on the dark web.</li><li><b>Remote work has expanded the attack surface:</b> Home networks are less secure than corporate networks. Remote workers are targeted 3x more frequently.</li></ul>`),{id:e(),...i(a.cybersecurity,`Digital security concept with lock and circuit board`)},t.callout(`<p><strong>Shocking Stat:</strong> A ransomware attack occurs every 11 seconds. The average cost of a data breach is $4.45 million. Prevention is not optional — it is essential.</p>`,`danger`)],{desc:`Real-world breach examples, costs of cybercrime, and why everyone is a target.`,duration:12}),n(`Common Attack Types`,`accordion`,[t.accordion(`Know Your Enemy — Common Cyber Attacks`,[{title:`Phishing`,content:`<p>The most common and dangerous attack. Fraudulent emails, texts, or calls that appear to come from a trusted source. <b>Goal:</b> Trick you into revealing passwords, clicking malicious links, or transferring money. <b>Red flags:</b> Urgency ("Act now!"), generic greetings ("Dear Customer"), mismatched sender addresses, unexpected attachments.</p>`},{title:`Ransomware`,content:`<p>Malware that encrypts your files and demands payment to unlock them. <b>How it spreads:</b> Often through phishing emails or exploiting unpatched software. <b>Protection:</b> Regular backups (stored offline), keeping software updated, and never opening suspicious attachments.</p>`},{title:`Social Engineering`,content:`<p>Manipulation tactics that exploit human psychology rather than technical vulnerabilities. <b>Examples:</b> An attacker calls pretending to be IT support and asks for your password. <b>Defense:</b> Verify identities through a separate channel before sharing sensitive information.</p>`},{title:`Credential Stuffing`,content:`<p>Attackers take usernames and passwords leaked from one breach and try them on other sites. If you reuse passwords, one breach exposes all your accounts. <b>Protection:</b> Use unique passwords for every service — a password manager makes this easy.</p>`},{title:`Man-in-the-Middle (MITM)`,content:`<p>Attackers intercept communication between you and a legitimate service. Common on public Wi-Fi networks. <b>Protection:</b> Always use a VPN on public Wi-Fi. Look for the lock icon (HTTPS) in your browser.</p>`}])],{desc:`Phishing, ransomware, social engineering, malware — explained simply.`,duration:14}),n(`The Human Firewall`,`callout`,[t.text(`<h2>You Are the First Line of Defense</h2><p>Technology alone cannot stop every attack. <b>The most effective cybersecurity tool is an alert, informed person.</b> Every employee is a "human firewall" — a sensor that can detect and stop threats before they cause damage.</p>`),t.callout(`<p><strong>Your Role as a Human Firewall:</strong> Think before you click. Verify before you trust. Report anything suspicious — even if you are not sure. It is always better to report a false alarm than to ignore a real threat.</p>`,`info`),t.callout(`<p><strong>If You See Something Suspicious:</strong> 1) Do NOT click any links or download attachments. 2) Immediately report it to your IT/security team. 3) If you already clicked something, disconnect from the network and notify IT immediately — do not be embarrassed, speed matters.</p>`,`warning`),t.callout(`<p><strong>The Most Common Security Mistake:</strong> Assuming "it will not happen to me." Everyone is a target. Everyone is a defender.</p>`,`danger`)],{desc:`Why human behavior is the first and last line of defense.`,duration:8})]),r(`Defending Yourself`,[n(`Password Best Practices`,`steps`,[t.steps(`Build Unbreakable Password Habits`,[{title:`Step 1: Use a Password Manager`,content:`<p>This is the single most impactful security step you can take. A password manager (1Password, Bitwarden, LastPass) generates and stores unique, complex passwords for every account. You only need to remember one master password. <b>Do this today.</b></p>`},{title:`Step 2: Make Passwords Long, Not Complex`,content:`<p>Use a <b>passphrase</b> — 4+ random words strung together. Example: "correct-horse-battery-staple". Length beats complexity. A 16-character random password takes billions of years to crack; an 8-character one takes minutes.</p>`},{title:`Step 3: Never Reuse Passwords`,content:`<p>If one site is breached and you reuse that password elsewhere, all your accounts are compromised. A password manager eliminates this temptation by generating unique passwords automatically.</p>`},{title:`Step 4: Enable Two-Factor Authentication (2FA)`,content:`<p>Passwords alone are not enough. 2FA adds a second layer — something you <em>have</em> (your phone) in addition to something you <em>know</em> (your password). Use an authenticator app rather than SMS when possible — SMS can be intercepted.</p>`},{title:`Step 5: Check If You Have Been Compromised`,content:`<p>Visit haveibeenpwned.com and enter your email. This site tells you if your credentials have appeared in known data breaches. If they have, change those passwords immediately.</p>`}]),{id:e(),...i(a.password,`Digital security concept with password and shield`)}],{desc:`Strong passwords, password managers, and why you should never reuse passwords.`,duration:14}),n(`Spotting Phishing Emails`,`slide-layout`,[t.text(`<h2>Become a Phishing Detective</h2><p>Phishing emails are getting more sophisticated. AI-generated phishing emails have a <b>60% higher success rate</b> than traditional ones. Here is how to spot them:</p><h3>The SLAM Method</h3><ul><li><b>S — Sender:</b> Check the actual email address, not just the display name. "HR Department" might display, but the actual address could be "hr@company-hr-support.net" instead of "hr@yourcompany.com".</li><li><b>L — Links:</b> Hover over links before clicking. Watch for subtle misspellings: "micr0soft.com" instead of "microsoft.com", or "paypaI.com" (capital I instead of L).</li><li><b>A — Attachments:</b> Were you expecting this file? Is it an unusual format (.exe, .scr, .js)? Even .pdf and .docx files can contain malicious macros.</li><li><b>M — Message:</b> Does it create artificial urgency? Does it ask for sensitive information? Is the tone different from normal?</li></ul>`),{id:e(),...i(a.security,`Close-up of an email inbox with security alerts highlighted`)},t.callout(`<p><strong>Golden Rule:</strong> If you are even 1% suspicious, do not click. Contact the sender through a different channel (phone, Slack, in person) to verify. No legitimate organization will fault you for being cautious.</p>`,`warning`)],{desc:`Red flags in emails, links, and attachments — with real examples.`,duration:14}),n(`Multi-Factor Authentication`,`quiz-focus`,[t.text(`<h2>Your Second Layer of Defense</h2><p>Multi-Factor Authentication (MFA) combines two or more factors: <b>something you know</b> (password), <b>something you have</b> (phone/security key), and <b>something you are</b> (fingerprint/face).</p><h3>MFA Methods — Ranked by Security</h3><ol><li><b>Hardware Security Key</b> (YubiKey, Titan): The gold standard. Phishing-resistant.</li><li><b>Authenticator App</b> (Google Authenticator, Authy): Much more secure than SMS.</li><li><b>SMS/Text Message:</b> Better than nothing, but vulnerable to SIM-swapping.</li><li><b>Email Code:</b> Least secure — if your email is compromised, so is this method.</li></ol><p><b>Set up MFA on every account that offers it</b> — especially email, banking, social media, and work systems.</p>`),t.quiz([{q:`What does the "L" in the SLAM method for detecting phishing stand for?`,subtype:`multiple-choice`,options:[`Login`,`Links`,`Language`,`Location`],correct:1},{q:`A 16-character random password is significantly harder to crack than an 8-character one.`,subtype:`true-false`,correct:0},{q:`The most secure form of multi-factor authentication is a _______ security key.`,subtype:`fill-blank`,correct:`hardware`},{q:`Which of the following is the WEAKEST form of MFA?`,subtype:`multiple-choice`,options:[`Hardware security key`,`Authenticator app`,`SMS text message`,`Email code`],correct:3}])],{desc:`What MFA is, why it matters, and how to set it up everywhere.`,duration:12})]),r(`Safe Habits Every Day`,[n(`Secure Browsing & Public Wi-Fi`,`title-text`,[t.text(`<h2>Stay Safe Online — Every Day</h2><p>The internet is full of hidden dangers. Here is how to browse safely:</p><h3>Essential Browsing Habits</h3><ul><li><b>Look for HTTPS:</b> The lock icon means your connection is encrypted. Never enter passwords or credit card info on HTTP sites.</li><li><b>Keep your browser updated:</b> Browser updates frequently include security patches. Enable automatic updates.</li><li><b>Be wary of browser extensions:</b> Extensions can read everything you do online. Only install from trusted developers. Review installed extensions quarterly.</li><li><b>Use a VPN on public Wi-Fi:</b> Coffee shops, airports, hotels — these networks are often unencrypted. A VPN encrypts everything.</li><li><b>Avoid sensitive transactions on public networks:</b> Do not log into your bank on public Wi-Fi — even with a VPN, wait for a trusted connection.</li></ul>`),t.callout(`<p><strong>Public Wi-Fi Tip:</strong> Your phone's hotspot is far more secure than any public Wi-Fi. If you need to do something sensitive while out, tether to your phone instead.</p>`,`tip`)],{desc:`VPN usage, HTTPS, avoiding public Wi-Fi risks.`,duration:10}),n(`Data Protection & Privacy`,`two-col`,[t.text(`<h2>Protect Sensitive Information</h2><p>Data protection is not just for IT — it is for everyone who handles any kind of sensitive information.</p><h3>Data Classification</h3><ul><li><b>Public:</b> Can be shared freely — marketing materials, public reports</li><li><b>Internal:</b> For team members only — project plans, internal docs</li><li><b>Confidential:</b> Limited access — customer data, financials, HR records</li><li><b>Restricted:</b> Strictly controlled — legal documents, trade secrets</li></ul>`),t.text(`<h3>Everyday Data Protection</h3><ul><li><b>Clean desk policy:</b> Lock your screen when you step away — even at home. Win+L on Windows, Ctrl+Cmd+Q on Mac.</li><li><b>Encrypt devices:</b> Ensure full-disk encryption is enabled (BitLocker for Windows, FileVault for Mac — both built-in and free).</li><li><b>Secure file sharing:</b> Use company-approved tools — not personal accounts. Never email sensitive files unencrypted.</li><li><b>Proper disposal:</b> Shred physical documents with sensitive data. Use secure erase tools before disposing of old devices.</li></ul>`)],{desc:`Handling sensitive data, device encryption, and clean desk policy.`,duration:10}),n(`What to Do If You Are Hacked`,`steps`,[t.steps(`Incident Response — Act Fast`,[{title:`Step 1: Disconnect Immediately`,content:`<p>Unplug your network cable or turn off Wi-Fi. <b>Do not turn off the device</b> — IT may need to examine it. Disconnecting stops the attacker from maintaining access and prevents malware from spreading.</p>`},{title:`Step 2: Report to IT/Security Team`,content:`<p>Contact your IT or security team immediately. Tell them: what you observed, what you clicked (if anything), and when it happened. Speed of reporting matters more than anything.</p>`},{title:`Step 3: Change Passwords — From a Clean Device`,content:`<p>Use a different, known-clean device to change passwords for critical accounts: email first, then banking, then work systems. If the attacker has your email, they can reset any other password.</p>`},{title:`Step 4: Scan for Malware`,content:`<p>Run a full antivirus/anti-malware scan on the affected device. IT may provide enterprise tools. Malware often hides and waits before activating.</p>`},{title:`Step 5: Check for Unauthorized Activity`,content:`<p>Review recent account activity: sent emails, login locations, file access, financial transactions. Enable login notifications if they are not already on.</p>`},{title:`Step 6: Learn & Share`,content:`<p>After the incident is resolved, understand what happened and how to prevent it. Share your experience with your team — your story could prevent someone else from falling for the same attack.</p>`}]),t.callout(`<p><strong>Critical Reminder:</strong> The average time to detect a breach is 207 days. By reporting immediately, you cut that to minutes — potentially saving millions.</p>`,`danger`)],{desc:`Immediate response steps: disconnect, report, change passwords, scan.`,duration:12}),n(`Final Security Assessment`,`assessment`,[t.text(`<h2>Cybersecurity Essentials — Final Assessment</h2><p>Congratulations on completing the course! This final assessment tests your understanding of key concepts across all three modules. Passing score: 80%.</p>`),t.quiz([{q:`What percentage of data breaches involve the human element?`,subtype:`multiple-choice`,options:[`25%`,`50%`,`74%`,`90%`],correct:2},{q:`It is safe to click a link in an email as long as the display name looks legitimate.`,subtype:`true-false`,correct:1},{q:`The single most impactful security step an individual can take is to use a _______ manager.`,subtype:`fill-blank`,correct:`password`},{q:`What should you do FIRST if you suspect your device has been compromised?`,subtype:`multiple-choice`,options:[`Turn off the device completely`,`Disconnect from the network and report to IT`,`Run a virus scan`,`Change your passwords`],correct:1},{q:`Match each attack type with its description:`,subtype:`matching`,pairs:[{left:`Phishing`,right:`Fraudulent messages tricking you into revealing information`},{left:`Ransomware`,right:`Malware that encrypts files and demands payment`},{left:`Social Engineering`,right:`Manipulating people into breaking security procedures`},{left:`Credential Stuffing`,right:`Using leaked passwords to access other accounts`}]},{q:`Which MFA method is most secure?`,subtype:`multiple-choice`,options:[`SMS text message`,`Email code`,`Hardware security key`,`Phone call`],correct:2}])],{desc:`Comprehensive quiz covering all cybersecurity essentials.`,duration:15})])]})}];function c(e){return s.find(t=>t.id===e)}function l(e){let t=c(e);return t?t.getCourse():null}export{l as n,s as t};